using System;
using UnityEngine;
using NWH.WheelController3D;
namespace LWS.TruckBowling {
[Serializable]public sealed class BowlingHandling {
 public float approachGrip=1.4f,endGrip=.10f,oilExponent=1.25f,motorTorque=3.6f,brakeTorque=9,maxSpeed=17,approachSteer=26,laneSteer=7;
 public float lateralStiffness=.8f,rearSteeringSlip=.24f,committedPower=.10f,edgeAssist=.75f,edgeBand=.60f,outwardDamping=.6f;
 public float spinGripScale=.12f,carryAcceleration=.55f,carrySpeed=13;
}
// NWH is the only tire/suspension force authority. LWS sets sport surface/input policy.
[DefaultExecutionOrder(-20)]public sealed class BowlingTruck:MonoBehaviour {
 public Rigidbody body;public WheelController[] wheels;public BowlingLane lane;public BowlingHandling handling=new BowlingHandling();public GameObject exterior;
 public AudioSource engine,skid;public float throttle,steer;public float Grip{get;private set;}public float AssistAcceleration{get;private set;}public float CarryAcceleration{get;private set;}public bool ControlLost{get;private set;}public float Speed=>body.linearVelocity.magnitude;public int PinImpacts{get;private set;}
 readonly BowlingPin[] tirePins=new BowlingPin[4];readonly RaycastHit[] carryHits=new RaycastHit[16];Collider[] colliders;BoxCollider chassis;bool braking;float nextImpact;
 void Start(){colliders=GetComponentsInChildren<Collider>(true);chassis=GetComponent<BoxCollider>();Stop();}
 public void Control(Vector2 input){steer=Mathf.Clamp(input.x,-1,1);throttle=Mathf.Clamp(input.y,-1,1);}
 public void Stop(){steer=throttle=0;foreach(var w in wheels){w.MotorTorque=w.BrakeTorque=0;w.SteerAngle=0;}}
 public void IgnorePins(BowlingPin[] pins,bool ignore){if(colliders==null)colliders=GetComponentsInChildren<Collider>(true);foreach(var c in colliders)foreach(var p in pins)if(c!=null)Physics.IgnoreCollision(c,p.GetComponent<Collider>(),ignore);}
 public void Clear(){if(colliders==null)colliders=GetComponentsInChildren<Collider>(true);Stop();foreach(var w in wheels)w.enabled=false;if(!body.isKinematic){body.linearVelocity=body.angularVelocity=Vector3.zero;}body.isKinematic=true;foreach(var c in colliders)if(c!=null)c.enabled=false;if(engine!=null)engine.Stop();if(skid!=null)skid.Stop();}
 public void Spawn(Vector3 pos){Clear();body.position=pos;body.rotation=Quaternion.identity;body.isKinematic=false;foreach(var c in colliders)if(c!=null)c.enabled=true;foreach(var w in wheels){w.wheel.angularVelocity=0;w.enabled=true;w.WakeFromSleep();}braking=false;exterior.SetActive(true);IgnorePins(lane.pins,false);lane.match.BindLaneCollision(lane);body.WakeUp();}
 void FixedUpdate(){CarryAcceleration=0;if(lane==null||!lane.MotionLive||!lane.match.DeliveryAllowed||lane.match.Paused||body.isKinematic){Stop();return;}float progress=Mathf.Clamp01(lane.Furthest/lane.pinLine);float slick=Mathf.Pow(progress,handling.oilExponent);Grip=Mathf.Lerp(handling.approachGrip,handling.endGrip,slick);var forward=body.rotation*Vector3.forward;float heading=Mathf.Abs(Vector3.SignedAngle(Vector3.forward,forward,Vector3.up));ControlLost=lane.Committed&&(lane.Gutter||heading>65||(body.rotation*Vector3.up).y<.45f);float local=Vector3.Dot(body.linearVelocity,forward);if(!braking&&throttle*local<-.12f&&Mathf.Abs(local)>.25f)braking=true;if(braking&&(Mathf.Abs(local)<.12f||throttle*local>=0))braking=false;
  float authority=lane.Committed?Mathf.Lerp(handling.committedPower,.008f,progress):1;bool controlled=lane.Driving&&!ControlLost;float motor=!controlled||braking||Speed>=handling.maxSpeed?0:throttle*handling.motorTorque*authority;float brake=controlled&&braking?handling.brakeTorque*Mathf.Abs(throttle)*authority:0;float spinGrip=lane.Committed?Mathf.Lerp(1,handling.spinGripScale,Mathf.SmoothStep(0,1,Mathf.InverseLerp(25,80,heading))):1;
  int grounded=0;for(int i=0;i<wheels.Length;i++){var w=wheels[i];if(w.IsGrounded)grounded++;w.MotorTorque=motor;w.BrakeTorque=brake;w.SteerAngle=i<2&&controlled?steer*Mathf.Lerp(handling.approachSteer,handling.laneSteer,slick):0;w.LateralFrictionGrip=Grip*spinGrip*(i>=2?1-handling.rearSteeringSlip*Mathf.Abs(steer)*Mathf.Clamp01(Speed/12):1);w.LongitudinalFrictionGrip=Grip;w.LateralFrictionStiffness=handling.lateralStiffness;}
  for(int i=0;i<wheels.Length;i++){var w=wheels[i];BowlingPin p=w.enabled&&w.IsGrounded&&w.HitCollider!=null?w.HitCollider.GetComponent<BowlingPin>():null;if(p!=null&&p.lane==lane&&Vector3.Distance(w.transform.position,p.transform.position)<2){lane.LegalPinContact=true;if(tirePins[i]!=p)PinImpacts++;}tirePins[i]=p;}
  AssistAcceleration=0;if(lane.Committed&&!lane.Gutter){float x=body.position.x-lane.center;float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(lane.halfWidth-handling.edgeBand,lane.halfWidth,Mathf.Abs(x)));if(blend>0){float outward=Mathf.Max(0,body.linearVelocity.x*Mathf.Sign(x));AssistAcceleration=blend*Mathf.Min(handling.edgeAssist+outward*handling.outwardDamping,2);body.AddForce(Vector3.right*(-Mathf.Sign(x)*AssistAcceleration),ForceMode.Acceleration);}}
  // Shared world-lane carry only. It neither aims laterally nor pushes through pins/obstacles.
  if(lane.Committed&&grounded>=2&&body.position.z<lane.pinLine-3&&body.position.y>-.3f&&body.linearVelocity.z>.15f&&body.linearVelocity.z<handling.carrySpeed&&CarryPathClear()){CarryAcceleration=Mathf.Min(handling.carryAcceleration,(handling.carrySpeed-body.linearVelocity.z)*.15f);body.AddForce(Vector3.forward*CarryAcceleration,ForceMode.Acceleration);}
 }
 bool CarryPathClear(){if(chassis==null)chassis=GetComponent<BoxCollider>();Vector3 center=body.position+body.rotation*chassis.center,extent=Vector3.Scale(chassis.size*.45f,transform.lossyScale);int count=Physics.BoxCastNonAlloc(center,extent,Vector3.forward,carryHits,body.rotation,1.4f,~0,QueryTriggerInteraction.Ignore);if(count==carryHits.Length){foreach(var hit in Physics.BoxCastAll(center,extent,Vector3.forward,body.rotation,1.4f,~0,QueryTriggerInteraction.Ignore))if(BlocksCarry(hit))return false;return true;}for(int i=0;i<count;i++)if(BlocksCarry(carryHits[i]))return false;return true;}
 bool BlocksCarry(RaycastHit hit)=>hit.collider!=null&&hit.rigidbody!=body&&hit.normal.y<.6f;
 void Update(){if(engine==null||lane==null)return;bool audible=lane.Driving&&!lane.match.Paused&&Application.isFocused&&lane.match.settings.sfx>0;float volume=audible?lane.match.settings.sfx*.085f:0;engine.volume=volume;engine.pitch=.7f+Speed*.045f+Mathf.Abs(throttle)*.1f;if(audible&&!engine.isPlaying)engine.Play();if(!audible&&engine.isPlaying)engine.Stop();float slip=Mathf.Abs(Vector3.Dot(body.linearVelocity,transform.right));skid.volume=audible?Mathf.Clamp01(slip/5)*lane.match.settings.sfx*.12f:0;if(skid.volume>.005f&&!skid.isPlaying)skid.Play();if(skid.volume<=.005f&&skid.isPlaying)skid.Stop();}
 void OnCollisionEnter(Collision c){if(lane==null||!lane.ScoringLive)return;var pin=c.collider.GetComponent<BowlingPin>();if(pin==null||pin.lane!=lane)return;PinImpacts++;lane.LegalPinContact=true;if(Time.time<nextImpact)return;nextImpact=Time.time+.08f;lane.match.feedback.Play(1,c.relativeVelocity.magnitude);lane.match.feedback.Pulse(lane.Owner.pad,Mathf.Min(.25f,c.relativeVelocity.magnitude*.015f),.10f);lane.cab.Impact=Mathf.Min(.025f,c.relativeVelocity.magnitude*.001f);}
}
}
